import time

state = {"calls": 0}

def flaky_service():
    state["calls"] += 1
    if state["calls"] < 3:
        raise ConnectionError("temporary glitch")
    return "payload"

def call_with_retry(fn, max_attempts=4):
    delay = 0.1
    for attempt in range(1, max_attempts + 1):
        try:
            return fn()
        except ConnectionError:
            if attempt == max_attempts:
                raise
            print(f"attempt {attempt} failed; backing off {delay:.1f}s")
            time.sleep(delay)
            delay *= 2

print(call_with_retry(flaky_service))
print("total calls:", state["calls"])

state = {"calls": 0}

def always_down():
    state["calls"] += 1
    raise ConnectionError("service unreachable")

def call_with_retry(fn, max_attempts=3):
    for attempt in range(1, max_attempts + 1):
        try:
            return fn()
        except ConnectionError:
            print(f"attempt {attempt} failed")
            if attempt == max_attempts:
                raise

try:
    call_with_retry(always_down)
except ConnectionError as e:
    print("caller sees the failure:", e)
print("total attempts made:", state["calls"])

from contextlib import ExitStack

class Resource:
    def __init__(self, name):
        self.name = name
    def __enter__(self):
        print("open", self.name)
        return self
    def __exit__(self, *exc):
        print("close", self.name)

try:
    with ExitStack() as stack:
        a = stack.enter_context(Resource("a"))
        b = stack.enter_context(Resource("b"))
        raise ValueError("fail in the middle")
except ValueError:
    print("caller caught the failure")

